/// <summary>
/// NS Zelinka 20.02.24
/// </summary>
public void initFromJournalTable()
{
    InventJournalTable  inventJournalTable = this.journalTableData().journalTable();
    InventJournalTrans  inventJournalTrans = journalTrans;
    InventDim           inventdim;

    next initFromJournalTable();

    if (inventJournalTable.JournalType == InventJournalType::Movement ||
        inventJournalTable.JournalType == InventJournalType::LossProfit)
    {
        inventJournalTrans.DefaultDimension = inventJournalTrans.copyDimension(inventJournalTable.AVADefaultDimension);
    }

    if (inventJournalTable.JournalType == InventJournalType::Transfer)
    {
        inventdim = inventdim::findOrCreateBlank();
        inventdim.InventSiteId = inventJournalTable.AVAToInventSiteId;
        inventdim.InventLocationId = inventJournalTable.AVAToInventLocationId;
        inventdim.wMSLocationId = InventLocation::find(inventJournalTable.AVAToInventLocationId).WMSLocationIdDefaultReceipt;
        inventdim = inventdim::findOrCreate(inventdim);
        inventJournalTrans.ToInventDimId = inventdim.inventDimId;

        inventdim = inventJournalTrans.inventDim();
        inventdim.wMSLocationId = InventLocation::find(inventdim.InventLocationId).WMSLocationIdDefaultReceipt;
        inventdim = InventDim::findOrCreate(inventdim);
        inventJournalTrans.InventDimId = inventdim.inventDimId;
    }
}
